    "property_id": "PROP-5a6a79d5-asm-002",
    "audit_result": {
      "property_id": "PROP-5a6a79d5-asm-002",
      "classification": "potential-vulnerability",
      "code_path": "crates/transaction-pool/src/validate/eth.rs::validate_one_no_state::L456-488",
      "proof_trace": "Blob transaction validation (lines 456-488) checks fork activation, blob count, and sidecar type, but does not verify that blob transactions are not contract creations (to != None). EIP-4844 prohibits blob transactions from being create transactions, but pool validator lacks this check.",
      "attack_scenario": "Attacker submits EIP-4844 blob transaction with to=None (contract creation). Pool validator accepts it despite invalid field combination, polluting mempool with unexecutable transaction that wastes bandwidth and node resources until execution-layer rejection.",
      "checklist_id": "PROP-5a6a79d5-asm-002"
    },
    "text": "Transaction senders control all tx fields; validation must reject invalid field combinations.",
    "assertion": "forall tx: check_transaction(tx) validates type, fees, gas, nonce, balance, blobs, auth",
    "covers": "SG-006",
    "severity": "HIGH",
    "type": "assumption"
  }
}

if let Err(err) = ensure_intrinsic_gas(&transaction, &self.fork_tracker) {
    return Err(TransactionValidationOutcome::Invalid(transaction, err))
}

// light blob tx pre-checks
if transaction.is_eip4844() {
    // Cancun fork is required for blob txs
    if !self.fork_tracker.is_cancun_activated() {
        return Err(TransactionValidationOutcome::Invalid(
            transaction,
            InvalidTransactionError::TxTypeNotSupported.into(),
        ))
    }

    let blob_count = transaction.blob_count().unwrap_or(0);
    if blob_count == 0 {
        // no blobs
        return Err(TransactionValidationOutcome::Invalid(
            transaction,
            InvalidPoolTransactionError::Eip4844(
                Eip4844PoolTransactionError::NoEip4844Blobs,
            ),
        ))
    }

    let max_blob_count = self.fork_tracker.max_blob_count();
    if blob_count > max_blob_count {
        return Err(TransactionValidationOutcome::Invalid(
            transaction,
            InvalidPoolTransactionError::Eip4844(
                Eip4844PoolTransactionError::TooManyEip4844Blobs {
                    have: blob_count,
                    permitted: max_blob_count,
                },
            ),
        ))
    }
}

// Osaka validation of max tx gas.
if self.fork_tracker.is_osaka_activated() &&
    transaction.gas_limit() > MAX_TX_GAS_LIMIT_OSAKA
{
    return Err(TransactionValidationOutcome::Invalid(
        transaction,
        InvalidTransactionError::GasLimitTooHigh.into(),
    ))
}

